# --- cs #784: cut decided, rows NOT written (an explicit gap): these keep their proposed cut in `proposed` and carry no ops.
for _c, _ids in (('zho_for_jpn', ('S0127L01', 'S0139L02', 'S0030L02', 'S0137L02', 'S0094L01', 'S0123L01', 'S0101L01')), ('jpn_for_eng', ('S0524L02', 'S0524L01'))):
    for _d in D[_c]:
        if _d['id'] in _ids:
            _d['proposed'] = {k: _d.pop(k) for k in ('known', 'target', 'type', 'components', 'basket', 'add', 'extra', 'ack', 'ack_rows') if k in _d}
            _d['proposed'].pop('basket', None)
            _d['was_verdict'] = _d['verdict']; _d['verdict'] = 'kai'; _d['pov'] = 'hold'
            if not _d['why'].startswith('HOLD'):
                _d['why'] = "HOLD (cut proposed, rows owed — not validated). " + _d['why'] + " The rows of this basket have not been re-read against the new cut; several use the word with other objects and would need rewording."
